%% EEG ANALYSIS PIPELINE: SUBJECT-FIRST FEATURE EXTRACTION AND GROUP ANALYSIS
%
% This script loads the full-trial preprocessed EEG files generated by Step01,
% extracts subject-level EEG features, visualizes each feature, saves all
% subject-level outputs into one unified features.mat file, computes group-level
% averages, visualizes group-level features, and performs statistical analysis.
%
% Features that are extracted:
%   ERP:    - direct trial averages for MI-band and delta-band
%             data across all channels
%   PSD:    - windowed spectral power for delta/theta/mu/beta/gamma bands
%   ERDS:   - mu/beta ERD/ERS time courses across all channels
%   TFR:    - time-frequency representations across all channels
%   ASSI:   - homologous left/right electrode-pair asymmetry features
%   TOPO:   - channel-wise power summaries across frequency bands
%
% Workflow:
%   1) Subject-level feature extraction
%   2) Immediate subject-level visualization right after extraction
%   3) Save everything in one unified data struct (features.mat)
%   4) Group-level visualization and statistical analysis from saved data
%
% INPUT: Preprocessed .mat files from Step01_Preprocessing_Healthy_Stroke.m
% OUTPUT: results/analysis/features.mat + visualization/stat outputs

clear; clc; close all;

%% ========================================================================
% CONFIGURATION
% ========================================================================

disp('Loading preprocessing configuration...');
config = Utility_Functions.get_preprocessing_config();
disp('Configuration loaded successfully.');

resultsPath = config.resultsPath;   % Root folder for all processed and analysis outputs
processedHealthyPath = fullfile(resultsPath, 'healthy_preprocessing');  % Step01 Healthy subject files
processedStrokePath  = fullfile(resultsPath, 'stroke_preprocessing');   % Step01 Stroke subject files
analysisResultsPath  = fullfile(resultsPath, 'analysis');               % Output folder for step02 features and plots
featuresMatPath      = fullfile(analysisResultsPath, 'features.mat');   % Unified feature output file

if ~exist(analysisResultsPath, 'dir')
    mkdir(analysisResultsPath);
end

% Modality-first output structure
modalityRoots = struct( ...
    'ERP',  fullfile(analysisResultsPath, 'ERP'), ...
    'PSD',  fullfile(analysisResultsPath, 'PSD'), ...
    'ERDS', fullfile(analysisResultsPath, 'ERDS'), ...
    'TOPO', fullfile(analysisResultsPath, 'TOPO'), ...
    'ASSI', fullfile(analysisResultsPath, 'ASSI'), ...
    'TFR',  fullfile(analysisResultsPath, 'TFR'));

% Creates folders for each feature; both subject-level and group-level
featureFolders = {
    modalityRoots.ERP
    modalityRoots.PSD
    modalityRoots.ERDS
    modalityRoots.TOPO
    modalityRoots.ASSI
    modalityRoots.TFR

    fullfile(modalityRoots.ERP,  'subject_level')
    fullfile(modalityRoots.ERP,  'group_level')

    fullfile(modalityRoots.PSD,  'subject_level')
    fullfile(modalityRoots.PSD,  'group_level')

    fullfile(modalityRoots.ERDS, 'subject_level')
    fullfile(modalityRoots.ERDS, 'group_level')

    fullfile(modalityRoots.TOPO, 'subject_level')
    fullfile(modalityRoots.TOPO, 'group_level')

    fullfile(modalityRoots.ASSI, 'subject_level')
    fullfile(modalityRoots.ASSI, 'group_level')

    fullfile(modalityRoots.TFR,  'subject_level')
    fullfile(modalityRoots.TFR,  'group_level')

    fullfile(modalityRoots.TOPO, 'group_level', 'statistics')
    fullfile(modalityRoots.ERDS, 'group_level', 'statistics')
};

for i = 1:length(featureFolders)
    if ~exist(featureFolders{i}, 'dir')
        mkdir(featureFolders{i});
    end
end

disp(['Created results folder structure in: ' char(analysisResultsPath)]);

%% ========================================================================
% CONTROL FLAGS
% ========================================================================

doFeatureExtraction    = true;   % Turn on/off subject-level feature extraction
doSubjectVisualization = true;   % Turn on/off subject-level plotting
doGroupVisualization   = false;  % Turn on/off group-level plots from saved features
doStatisticalAnalysis  = false;  % Turn on/off statistical analysis

maxSubjectsToRun = 12;          % Controls how many total files are processed

% Subject-level visualization limits.
% These control plotting only; feature extraction still runs for all processed subjects.
maxHealthySubjectsToVisualize = 5;    % Example: save plots for first 5 healthy subjects
maxStrokeSubjectsToVisualize  = 5;    % Example: save plots for first 5 stroke subjects

%% ========================================================================
% SETTINGS
% ========================================================================

leftCode  = 1;  % Label code for left-hand MI trials
rightCode = 2;  % Label code for right-hand MI trials

% Later feature settings remain here for continuity
saveDeltaThetaTimeSeries = false;

erdersSmoothWin_sec = 0.25;      % Visualization-only smoothing for ERD/ERS plots
tfrSmoothWin_sec = 0.25;         % Visualization-only smoothing for TFR channel-time summaries

erdersColorLimits = [-75 75];    % Fixed ERD/ERS color limits in percent
tfrColorLimits = [-3 3];         % Fixed TFR color limits in dB; adjust to [-2 2] or [-4 4] after review

alpha = 0.05;

% PSD settings
psdBandNames = {'delta','theta','mu','beta','gamma'};
psdEpochFields = {'epochsDelta','epochsTheta','epochsMu','epochsBeta','epochsGamma'};
psdBandRanges = {
    config.deltaBand
    config.thetaBand
    config.muBand
    config.betaBand
    config.gammaBand
};

% ERD/ERS settings
erdersBands = {'mu','beta'};

tfrBandDefs = struct();
tfrBandDefs.mu.name = 'mu';
tfrBandDefs.mu.range = [8 13];

tfrBandDefs.beta.name = 'beta';
tfrBandDefs.beta.range = [13 30];

tfrBandDefs.broad.name = 'broad_8_30';
tfrBandDefs.broad.range = [8 30];

% ASSI settings
assiBandNames = {'delta','theta','mu','beta','gamma'};

% TOPO/channel-power settings
topoBandNames = {'delta','theta','mi','mu','beta','gamma'};
topoEpochFields = {'epochsDelta','epochsTheta','epochsMI','epochsMu','epochsBeta','epochsGamma'};

%% ========================================================================
% MASTER DATA STRUCT
% ========================================================================

data = struct();

data.meta.createdOn = datestr(now);
data.meta.schemaVersion = 'v4_subject_first_full_trial';
data.meta.sourceScript = mfilename;
data.meta.analysisResultsPath = analysisResultsPath;
data.meta.modalityRoots = modalityRoots;

data.meta.flags = struct( ...
    'doFeatureExtraction', doFeatureExtraction, ...
    'doSubjectVisualization', doSubjectVisualization, ...
    'doGroupVisualization', doGroupVisualization, ...
    'doStatisticalAnalysis', doStatisticalAnalysis);

data.config = struct( ...
    'leftCode', leftCode, ...
    'rightCode', rightCode, ...
    'windowMode', 'subjectOut_saved_dataset_specific_windows', ...
    'erpBands', {{'MI','Delta'}}, ...
    'psdBandNames', {psdBandNames}, ...
    'erdersBands', {erdersBands}, ...
    'assiBandNames', {assiBandNames}, ...
    'topoBandNames', {topoBandNames}, ...
    'saveDeltaThetaTimeSeries', saveDeltaThetaTimeSeries, ...
    'erdersSmoothWin_sec', erdersSmoothWin_sec, ...
    'tfrSmoothWin_sec', tfrSmoothWin_sec, ...
    'erdersColorLimits', erdersColorLimits, ...
    'tfrColorLimits', tfrColorLimits, ...
    'tfrBandDefs', tfrBandDefs, ...
    'alpha', alpha);

%% ========================================================================
% PART 1: SUBJECT-LEVEL EXTRACTION + IMMEDIATE SUBJECT VISUALIZATION
% ========================================================================

if doFeatureExtraction

    disp(' ');
    disp('================================================================================');
    disp('PART 1: SUBJECT-LEVEL EXTRACTION + IMMEDIATE VISUALIZATION');
    disp('================================================================================');

    healthyFiles = dir(fullfile(processedHealthyPath, "*_processed.mat"));
    strokeFiles  = dir(fullfile(processedStrokePath, "*_processed.mat"));
    fileList = [healthyFiles; strokeFiles];

    if isempty(fileList)
        error('No processed files found in %s or %s.', processedHealthyPath, processedStrokePath);
    end

    disp(['Found ' num2str(length(fileList)) ' files (' ...
        num2str(length(healthyFiles)) ' healthy, ' ...
        num2str(length(strokeFiles)) ' stroke).']);

    subjectFeatures = struct([]);
    summarySubjects = struct([]);

    healthyERP = struct([]);
    strokeERP  = struct([]);
    
    healthyPSD = struct([]);
    strokePSD  = struct([]);

    healthyERDS = struct([]);
    strokeERDS  = struct([]);
    
    healthyTFR = struct([]);
    strokeTFR  = struct([]);
    
    healthyASSI = struct([]);
    strokeASSI  = struct([]);
    
    healthyTOPO = struct([]);
    strokeTOPO  = struct([]);
    
    chanLabels_ref = [];
    validCount = 0;
    healthyCount = 0;
    strokeCount = 0;
    healthyPSDCount = 0;
    strokePSDCount = 0;
    healthyERDSCount = 0;
    strokeERDSCount = 0;
    healthyTFRCount = 0;
    strokeTFRCount = 0;
    healthyASSICount = 0;
    strokeASSICount = 0;
    healthyTOPOCount = 0;
    strokeTOPOCount = 0;

    nFilesToRun = min(length(fileList), maxSubjectsToRun);
    
    % Visualization counters are separate from extraction counters.
    % This allows all subjects to be processed while only plotting a subset.
    healthyVisualizedCount = 0;
    strokeVisualizedCount = 0;
    
    for i = 1:nFilesToRun

        fname = fileList(i).name;
        fpath = fullfile(fileList(i).folder, fname);

        fprintf('\nProcessing file %d/%d: %s\n', i, length(fileList), fname);

        %% Determine group

        if startsWith(fname, "S")
            groupType = "healthy";
        elseif startsWith(lower(fname), "sub-")
            groupType = "stroke";
        else
            error('Unknown filename pattern for file: %s. Expected healthy files to start with S and stroke files to start with sub-.', fname);
        end

        %% Decide whether to visualize this subject
        % Feature extraction still runs regardless. This only controls plot saving.
        
        doThisSubjectVisualization = true;
        
        if doThisSubjectVisualization
        
            if strcmpi(char(groupType), 'healthy')
        
                if healthyVisualizedCount < maxHealthySubjectsToVisualize
                    doThisSubjectVisualization = true;
                    healthyVisualizedCount = healthyVisualizedCount + 1;
                end
        
            elseif strcmpi(char(groupType), 'stroke')
        
                if strokeVisualizedCount < maxStrokeSubjectsToVisualize
                    doThisSubjectVisualization = true;
                    strokeVisualizedCount = strokeVisualizedCount + 1;
                end
            end
        end
        
        fprintf('Subject visualization for %s: %s\n', ...
            fname, string(doThisSubjectVisualization));

        %% Load subjectOut

        D = load(fpath);
        
        if ~isfield(D, 'subjectOut')
            error('File %s does not contain subjectOut. Check Step01 output.', fname);
        end
        
        S = D.subjectOut;

        %% Required fields for subject-wise ERP

        requiredFields = { ...
            'subjectName', ...
            'fs', ...
            'tEpoch', ...
            'chanLabels', ...
            'labels', ...
            'epochsMI', ...
            'epochsDelta', ...
            'epochsTheta', ...
            'epochsMu', ...
            'epochsBeta', ...
            'epochsGamma', ...
            'baselineWindow', ...
            'miWindow', ...
            'cueTimeSec'};

        missing = requiredFields(~isfield(S, requiredFields));
        
        if ~isempty(missing)
            error('File %s is missing required subjectOut fields: %s', ...
                fname, strjoin(missing, ', '));
        end

        %% Pull subject variables

        subjectName = S.subjectName;
        fs = S.fs;
        t = S.tEpoch(:)';
        chanLabels = S.chanLabels;
        labels = S.labels(:);

        Xmi = S.epochsMI;
        Xdelta = S.epochsDelta;
        Xtheta = S.epochsTheta;
        Xmu = S.epochsMu;
        Xbeta = S.epochsBeta;
        Xgamma = S.epochsGamma;

        cueTimeSec = S.cueTimeSec;  % Cue/MI onset time in full-trial coordinates

        % Use dataset-specific timing saved from Step01.
        % Healthy files are annotation-defined and MI-onset aligned.
        % Stroke files remain full-trial aligned.
        baselineWindow = S.baselineWindow;
        miWindow = S.miWindow;
        
        if isfield(S, 'analysisWindowSize')
            analysisWindowSize = S.analysisWindowSize;
        else
            analysisWindowSize = miWindow(2) - miWindow(1);
        end

        xLimits = [t(1) t(end)];

        %% Basic checks

        if isempty(chanLabels_ref)
            chanLabels_ref = chanLabels;
        else
            if length(chanLabels) ~= length(chanLabels_ref) || ...
                    ~all(strcmpi(chanLabels(:), chanLabels_ref(:)))
            
                error(['Channel mismatch in file %s.\n' ...
                       'This subject does not match the reference channel set.\n' ...
                       'Check Step01 channel harmonization before continuing.'], fname);
            end
        end

        nTrials = length(labels);

        baselineIdx = t >= baselineWindow(1) & t < baselineWindow(2);
        miIdx = t >= miWindow(1) & t < miWindow(2);

        if ~any(baselineIdx) || ~any(miIdx)
            error(['Empty baseline or MI window in file %s.\n' ...
                   'baselineWindow = [%.2f %.2f]\n' ...
                   'miWindow       = [%.2f %.2f]\n' ...
                   't range        = [%.2f %.2f]\n' ...
                   'Check dataset-specific window definitions and Step01 full-trial timing.'], ...
                   fname, ...
                   baselineWindow(1), baselineWindow(2), ...
                   miWindow(1), miWindow(2), ...
                   t(1), t(end));
        end

        %% Create subject output directories

        modalityNames = fieldnames(modalityRoots);

        subjDirs = struct();

        for mm = 1:length(modalityNames)
            modalityName = modalityNames{mm};

            subjDirs.(modalityName) = fullfile( ...
                modalityRoots.(modalityName), ...
                'subject_level', ...
                char(subjectName));

            if ~exist(subjDirs.(modalityName), 'dir')
                mkdir(subjDirs.(modalityName));
            end
        end

        %% =================================================================
        % ERP FEATURE: SUBJECT-WISE, ALL CHANNELS, MI BAND + DELTA BAND
        % =================================================================

        fprintf('Extracting ERP features for %s (%s)...\n', ...
            char(subjectName), char(groupType));

        erpSubject = struct();

        erpSubject.subjectName = subjectName;
        erpSubject.group = char(groupType);
        erpSubject.fs = fs;
        erpSubject.t = t;
        erpSubject.chanLabels = chanLabels;
        erpSubject.labels = labels;
        erpSubject.nTrials = nTrials;
        erpSubject.baselineWindow = baselineWindow;
        erpSubject.miWindow = miWindow;
        erpSubject.cueTimeSec = cueTimeSec;
        erpSubject.xLimits = xLimits;

        % MI-band ERP
        erpMI = Utility_Functions.compute_subject_channel_erp( ...
            Xmi, labels, t, chanLabels, leftCode, rightCode);

        erpMI.subjectName = subjectName;
        erpMI.group = char(groupType);
        erpMI.band = 'MI';
        erpMI.fs = fs;
        erpMI.cueTimeSec = cueTimeSec;
        erpMI.baselineWindow = baselineWindow;
        erpMI.miWindow = miWindow;
        erpMI.xLimits = xLimits;

        erpSubject.MI = erpMI;

        % Delta-band ERP
        erpDelta = Utility_Functions.compute_subject_channel_erp( ...
            Xdelta, labels, t, chanLabels, leftCode, rightCode);

        erpDelta.subjectName = subjectName;
        erpDelta.group = char(groupType);
        erpDelta.band = 'Delta';
        erpDelta.fs = fs;
        erpDelta.cueTimeSec = cueTimeSec;
        erpDelta.baselineWindow = baselineWindow;
        erpDelta.miWindow = miWindow;
        erpDelta.xLimits = xLimits;

        erpSubject.Delta = erpDelta;

        %% Save ERP data immediately

        erpMatPath = fullfile(subjDirs.ERP, [char(subjectName) '_ERP_MI_Delta.mat']);
        save(erpMatPath, 'erpSubject', '-v7.3');

        %% Immediate ERP visualization

        if doThisSubjectVisualization

            % MI band: all channels
            Utility_Functions.plot_erp_all_channels_with_windows( ...
                t, erpMI, chanLabels, ...
                baselineWindow, miWindow, cueTimeSec, ...
                fullfile(subjDirs.ERP, [char(subjectName) '_ERP_MI_all_channels']), ...
                [char(subjectName) ' | ' char(groupType) ' | MI-band ERP']);
            
            % Delta band: all channels
            Utility_Functions.plot_erp_all_channels_with_windows( ...
                t, erpDelta, chanLabels, ...
                baselineWindow, miWindow, cueTimeSec, ...
                fullfile(subjDirs.ERP, [char(subjectName) '_ERP_Delta_all_channels']), ...
                [char(subjectName) ' | ' char(groupType) ' | Delta-band ERP']);
        end

        %% =================================================================
        % PSD FEATURE: SUBJECT-WISE, ALL CHANNELS, ALL BANDS
        % =================================================================

        fprintf('Extracting PSD features for %s (%s)...\n', ...
            char(subjectName), char(groupType));

        psdSubject = struct();

        psdSubject.subjectName = subjectName;
        psdSubject.group = char(groupType);
        psdSubject.fs = fs;
        psdSubject.t = t;
        psdSubject.chanLabels = chanLabels;
        psdSubject.labels = labels;
        psdSubject.nTrials = nTrials;
        psdSubject.baselineWindow = baselineWindow;
        psdSubject.miWindow = miWindow;
        psdSubject.cueTimeSec = cueTimeSec;
        psdSubject.bandNames = psdBandNames;

        for b = 1:length(psdBandNames)

            bandName = psdBandNames{b};
            epochField = psdEpochFields{b};
            bandRange = psdBandRanges{b};

            epochsBand = S.(epochField);

            psdOut = Utility_Functions.compute_subject_channel_psd_by_condition( ...
                epochsBand, labels, fs, baselineIdx, miIdx, bandRange, leftCode, rightCode);

            psdOut.bandName = bandName;
            psdOut.bandRange = bandRange;
            psdOut.subjectName = subjectName;
            psdOut.group = char(groupType);
            psdOut.chanLabels = chanLabels;
            psdOut.baselineWindow = baselineWindow;
            psdOut.miWindow = miWindow;
            psdOut.cueTimeSec = cueTimeSec;

            psdSubject.(bandName) = psdOut;

            if doThisSubjectVisualization
            
                % Primary dB plot: use for interpretation and statistics consistency.
                Utility_Functions.plot_subject_psd_bars_by_condition( ...
                    psdOut, chanLabels, ...
                    fullfile(subjDirs.PSD, [char(subjectName) '_PSD_' bandName '_dB']), ...
                    [char(subjectName) ' | ' char(groupType) ' | ' upper(bandName) ' Band Power (dB)'], ...
                    'db');
            
                % Secondary linear plot: inspection/debugging only.
                Utility_Functions.plot_subject_psd_bars_by_condition( ...
                    psdOut, chanLabels, ...
                    fullfile(subjDirs.PSD, [char(subjectName) '_PSD_' bandName '_linear']), ...
                    [char(subjectName) ' | ' char(groupType) ' | ' upper(bandName) ' Band Power (Linear)'], ...
                    'linear');
            end
        end

        psdMatPath = fullfile(subjDirs.PSD, [char(subjectName) '_PSD_all_bands.mat']);
        save(psdMatPath, 'psdSubject', '-v7.3');

        %% =================================================================
        % ERD/ERS FEATURE: SUBJECT-WISE MU AND BETA, ALL CHANNELS
        % =================================================================
        
        fprintf('Extracting ERD/ERS features for %s (%s)...\n', ...
            char(subjectName), char(groupType));
        
        erdsSubject = struct();
        erdsSubject.subjectName = subjectName;
        erdsSubject.group = char(groupType);
        erdsSubject.fs = fs;
        erdsSubject.t = t;
        erdsSubject.chanLabels = chanLabels;
        erdsSubject.labels = labels;
        erdsSubject.nTrials = nTrials;
        erdsSubject.baselineWindow = baselineWindow;
        erdsSubject.miWindow = miWindow;
        erdsSubject.cueTimeSec = cueTimeSec;
        
        % Saved ERD/ERS values are unsmoothed.
        % Smoothing is applied only inside the plotting function.
        erdsSubject.plotSmoothWin_sec = erdersSmoothWin_sec;
        erdsSubject.plotColorLimits = erdersColorLimits;
        
        erdsSubject.mu = Utility_Functions.compute_subject_erders_all_channels( ...
            Xmu, labels, baselineIdx, leftCode, rightCode);
        
        erdsSubject.beta = Utility_Functions.compute_subject_erders_all_channels( ...
            Xbeta, labels, baselineIdx, leftCode, rightCode);
        
        if doThisSubjectVisualization
            Utility_Functions.plot_subject_erders_all_channels( ...
                erdsSubject, ...
                fullfile(subjDirs.ERDS, [char(subjectName) '_ERDS_all_channels']), ...
                [char(subjectName) ' | ' char(groupType) ' | All-Channel Mu/Beta ERD/ERS']);
        end
        
        erdsMatPath = fullfile(subjDirs.ERDS, [char(subjectName) '_ERDS_all_channels.mat']);
        save(erdsMatPath, 'erdsSubject', '-v7.3');

        %% =================================================================
        % TFR FEATURE: SUBJECT-WISE CHANNEL-TIME SUMMARIES
        % =================================================================
        
        fprintf('Extracting TFR features for %s (%s)...\n', ...
            char(subjectName), char(groupType));
        
        tfrSubject = struct();
        tfrSubject.subjectName = subjectName;
        tfrSubject.group = char(groupType);
        tfrSubject.fs = fs;
        tfrSubject.t = t;
        tfrSubject.chanLabels = chanLabels;
        tfrSubject.labels = labels;
        tfrSubject.baselineWindow = baselineWindow;
        tfrSubject.miWindow = miWindow;
        tfrSubject.cueTimeSec = cueTimeSec;
        tfrSubject.plotColorLimits = tfrColorLimits;
        tfrSubject.plotSmoothWin_sec = tfrSmoothWin_sec;
        
        leftIdx = labels == leftCode;
        rightIdx = labels == rightCode;
        
        nCh = length(chanLabels);
        
        tfrSubject.bands = struct();
        tfrBandNames = fieldnames(tfrBandDefs);
        
        for tb = 1:length(tfrBandNames)
        
            tfrBandName = tfrBandNames{tb};
            thisRange = tfrBandDefs.(tfrBandName).range;
        
            fprintf('  Computing TFR band: %s [%.1f %.1f] Hz\n', ...
                tfrBandName, thisRange(1), thisRange(2));
        
            tfrSubject.bands.(tfrBandName).name = tfrBandName;
            tfrSubject.bands.(tfrBandName).range = thisRange;
            tfrSubject.bands.(tfrBandName).left = struct();
            tfrSubject.bands.(tfrBandName).right = struct();
        
            f_tfr = [];
        
            for ch = 1:nCh
        
                chName = matlab.lang.makeValidName(chanLabels{ch});
        
                [leftTFR, f_tfr] = Utility_Functions.compute_time_frequency( ...
                    squeeze(Xmi(ch,:,leftIdx)), fs, thisRange, t, baselineWindow);
        
                [rightTFR, ~] = Utility_Functions.compute_time_frequency( ...
                    squeeze(Xmi(ch,:,rightIdx)), fs, thisRange, t, baselineWindow);
        
                tfrSubject.bands.(tfrBandName).left.(chName) = leftTFR;
                tfrSubject.bands.(tfrBandName).right.(chName) = rightTFR;
            end
        
            tfrSubject.bands.(tfrBandName).f = f_tfr;
        end
        
        if doThisSubjectVisualization
            Utility_Functions.plot_subject_tfr_all_channels( ...
                tfrSubject, tfrColorLimits, ...
                fullfile(subjDirs.TFR, [char(subjectName) '_TFR_channel_time_summary']), ...
                [char(subjectName) ' | ' char(groupType) ' | TFR Channel-Time Summary']);
        end
        
        tfrMatPath = fullfile(subjDirs.TFR, [char(subjectName) '_TFR_channel_time_summary.mat']);
        save(tfrMatPath, 'tfrSubject', '-v7.3');

        %% =================================================================
        % ASSI FEATURE: SUBJECT-WISE ALL LEFT/RIGHT ELECTRODE PAIRS
        % =================================================================

        fprintf('Extracting ASSI features for %s (%s)...\n', ...
            char(subjectName), char(groupType));

        deltaSummary = Utility_Functions.compute_channel_band_power_with_baseline( ...
            Xdelta, labels, leftCode, rightCode, baselineIdx, miIdx);

        thetaSummary = Utility_Functions.compute_channel_band_power_with_baseline( ...
            Xtheta, labels, leftCode, rightCode, baselineIdx, miIdx);

        muSummary = Utility_Functions.compute_channel_band_power_with_baseline( ...
            Xmu, labels, leftCode, rightCode, baselineIdx, miIdx);

        betaSummary = Utility_Functions.compute_channel_band_power_with_baseline( ...
            Xbeta, labels, leftCode, rightCode, baselineIdx, miIdx);

        gammaSummary = Utility_Functions.compute_channel_band_power_with_baseline( ...
            Xgamma, labels, leftCode, rightCode, baselineIdx, miIdx);

        assiSubject = Utility_Functions.compute_summary_allpair_asymmetry( ...
            deltaSummary, thetaSummary, muSummary, betaSummary, gammaSummary, chanLabels);

        assiSubject.subjectName = subjectName;
        assiSubject.group = char(groupType);
        assiSubject.fs = fs;
        assiSubject.t = t;
        assiSubject.chanLabels = chanLabels;
        assiSubject.labels = labels;
        assiSubject.nTrials = nTrials;
        assiSubject.bandNames = assiBandNames;
        assiSubject.baselineWindow = baselineWindow;
        assiSubject.miWindow = miWindow;
        assiSubject.cueTimeSec = cueTimeSec;

        if doThisSubjectVisualization
            Utility_Functions.plot_subject_allpair_assi( ...
                assiSubject, ...
                fullfile(subjDirs.ASSI, [char(subjectName) '_ASSI_all_pairs']), ...
                [char(subjectName) ' | ' char(groupType) ' | All-Pair Lateralization']);
        end

        assiMatPath = fullfile(subjDirs.ASSI, [char(subjectName) '_ASSI_all_pairs.mat']);
        save(assiMatPath, 'assiSubject', '-v7.3');


        %% =================================================================
        % TOPO / CHANNEL POWER FEATURE: SUBJECT-WISE ALL CHANNELS
        % =================================================================

        fprintf('Extracting TOPO/channel-power features for %s (%s)...\n', ...
            char(subjectName), char(groupType));

        topoSubject = struct();
        topoSubject.subjectName = subjectName;
        topoSubject.group = char(groupType);
        topoSubject.fs = fs;
        topoSubject.t = t;
        topoSubject.chanLabels = chanLabels;
        topoSubject.labels = labels;
        topoSubject.nTrials = nTrials;
        topoSubject.baselineWindow = baselineWindow;
        topoSubject.miWindow = miWindow;
        topoSubject.cueTimeSec = cueTimeSec;
        topoSubject.bandNames = topoBandNames;

        for b = 1:length(topoBandNames)
        
            bandName = topoBandNames{b};
            epochField = topoEpochFields{b};
        
            if ~isfield(S, epochField)
                error('File %s is missing %s, which is required for TOPO/channel-power extraction.', ...
                    fname, epochField);
            end
        
            epochsBand = S.(epochField);
        
            leftBaselinePower = Utility_Functions.compute_channel_band_power_fft( ...
                epochsBand(:,:,labels == leftCode), fs, baselineIdx);
        
            rightBaselinePower = Utility_Functions.compute_channel_band_power_fft( ...
                epochsBand(:,:,labels == rightCode), fs, baselineIdx);
        
            leftMIPower = Utility_Functions.compute_channel_band_power_fft( ...
                epochsBand(:,:,labels == leftCode), fs, miIdx);
        
            rightMIPower = Utility_Functions.compute_channel_band_power_fft( ...
                epochsBand(:,:,labels == rightCode), fs, miIdx);
        
            % Store hand-specific and mean TOPO/channel-power values
            
            % Trial-averaged channel power for each condition
            topoSubject.(bandName).left_baseline_power = mean(leftBaselinePower, 2, 'omitnan');
            topoSubject.(bandName).right_baseline_power = mean(rightBaselinePower, 2, 'omitnan');
            
            topoSubject.(bandName).left_mi_power = mean(leftMIPower, 2, 'omitnan');
            topoSubject.(bandName).right_mi_power = mean(rightMIPower, 2, 'omitnan');
            
            % Mean summaries retained for broad visualization only
            topoSubject.(bandName).mean_baseline_power = mean([ ...
                topoSubject.(bandName).left_baseline_power, ...
                topoSubject.(bandName).right_baseline_power], 2, 'omitnan');
            
            topoSubject.(bandName).mean_mi_power = mean([ ...
                topoSubject.(bandName).left_mi_power, ...
                topoSubject.(bandName).right_mi_power], 2, 'omitnan');
            
            % Convert hand-specific and mean TOPO/channel-power values to dB
            
            topoSubject.(bandName).left_baseline_power_db = Utility_Functions.pow_to_db( ...
                topoSubject.(bandName).left_baseline_power);
            
            topoSubject.(bandName).right_baseline_power_db = Utility_Functions.pow_to_db( ...
                topoSubject.(bandName).right_baseline_power);
            
            topoSubject.(bandName).left_mi_power_db = Utility_Functions.pow_to_db( ...
                topoSubject.(bandName).left_mi_power);
            
            topoSubject.(bandName).right_mi_power_db = Utility_Functions.pow_to_db( ...
                topoSubject.(bandName).right_mi_power);
            
            topoSubject.(bandName).mean_baseline_power_db = Utility_Functions.pow_to_db( ...
                topoSubject.(bandName).mean_baseline_power);
            
            topoSubject.(bandName).mean_mi_power_db = Utility_Functions.pow_to_db( ...
                topoSubject.(bandName).mean_mi_power);
        end

        if doThisSubjectVisualization
            Utility_Functions.plot_subject_channel_power_summary( ...
                topoSubject, ...
                fullfile(subjDirs.TOPO, [char(subjectName) '_TOPO_channel_power']), ...
                [char(subjectName) ' | ' char(groupType) ' | Channel Power']);
        end

        topoMatPath = fullfile(subjDirs.TOPO, [char(subjectName) '_TOPO_channel_power.mat']);
        save(topoMatPath, 'topoSubject', '-v7.3');
        %% Save subject-level feature struct

        validCount = validCount + 1;

        subjectFeatures(validCount).fileName = fname;
        subjectFeatures(validCount).sourceFile = fpath;
        subjectFeatures(validCount).subjectName = subjectName;
        subjectFeatures(validCount).group = char(groupType);
        subjectFeatures(validCount).fs = fs;
        subjectFeatures(validCount).tEpoch = t;
        subjectFeatures(validCount).chanLabels = chanLabels;
        subjectFeatures(validCount).labels = labels;
        subjectFeatures(validCount).nTrials = nTrials;
        subjectFeatures(validCount).baselineWindow = baselineWindow;
        subjectFeatures(validCount).miWindow = miWindow;
        subjectFeatures(validCount).cueTimeSec = cueTimeSec;
        subjectFeatures(validCount).xLimits = xLimits;
        subjectFeatures(validCount).ERP = erpSubject;
        subjectFeatures(validCount).PSD = psdSubject;
        subjectFeatures(validCount).ERDS = erdsSubject;
        subjectFeatures(validCount).TFR = tfrSubject;
        subjectFeatures(validCount).ASSI = assiSubject;
        subjectFeatures(validCount).TOPO = topoSubject;

        summarySubjects(validCount).fileName = fname;
        summarySubjects(validCount).subjectName = subjectName;
        summarySubjects(validCount).group = char(groupType);
        summarySubjects(validCount).chanLabels = chanLabels;
        summarySubjects(validCount).tEpoch = t;
        summarySubjects(validCount).baselineWindow = baselineWindow;
        summarySubjects(validCount).miWindow = miWindow;
        summarySubjects(validCount).cueTimeSec = cueTimeSec;
        summarySubjects(validCount).xLimits = xLimits;
        summarySubjects(validCount).ERP = erpSubject;
        summarySubjects(validCount).PSD = psdSubject;
        summarySubjects(validCount).ERDS = erdsSubject;
        summarySubjects(validCount).TFR = tfrSubject;
        summarySubjects(validCount).ASSI = assiSubject;
        summarySubjects(validCount).TOPO = topoSubject;

        if strcmp(char(groupType), 'healthy')
            healthyCount = healthyCount + 1;
            healthyERP(healthyCount).subjectName = subjectName;
            healthyERP(healthyCount).ERP = erpSubject;
        
            healthyPSDCount = healthyPSDCount + 1;
            healthyPSD(healthyPSDCount).subjectName = subjectName;
            healthyPSD(healthyPSDCount).PSD = psdSubject;
        
            healthyERDSCount = healthyERDSCount + 1;
            healthyERDS(healthyERDSCount).subjectName = subjectName;
            healthyERDS(healthyERDSCount).ERDS = erdsSubject;
        
            healthyTFRCount = healthyTFRCount + 1;
            healthyTFR(healthyTFRCount).subjectName = subjectName;
            healthyTFR(healthyTFRCount).TFR = tfrSubject;
        
            healthyASSICount = healthyASSICount + 1;
            healthyASSI(healthyASSICount).subjectName = subjectName;
            healthyASSI(healthyASSICount).ASSI = assiSubject;
        
            healthyTOPOCount = healthyTOPOCount + 1;
            healthyTOPO(healthyTOPOCount).subjectName = subjectName;
            healthyTOPO(healthyTOPOCount).TOPO = topoSubject;
        else
            strokeCount = strokeCount + 1;
            strokeERP(strokeCount).subjectName = subjectName;
            strokeERP(strokeCount).ERP = erpSubject;
        
            strokePSDCount = strokePSDCount + 1;
            strokePSD(strokePSDCount).subjectName = subjectName;
            strokePSD(strokePSDCount).PSD = psdSubject;
        
            strokeERDSCount = strokeERDSCount + 1;
            strokeERDS(strokeERDSCount).subjectName = subjectName;
            strokeERDS(strokeERDSCount).ERDS = erdsSubject;
        
            strokeTFRCount = strokeTFRCount + 1;
            strokeTFR(strokeTFRCount).subjectName = subjectName;
            strokeTFR(strokeTFRCount).TFR = tfrSubject;
        
            strokeASSICount = strokeASSICount + 1;
            strokeASSI(strokeASSICount).subjectName = subjectName;
            strokeASSI(strokeASSICount).ASSI = assiSubject;
        
            strokeTOPOCount = strokeTOPOCount + 1;
            strokeTOPO(strokeTOPOCount).subjectName = subjectName;
            strokeTOPO(strokeTOPOCount).TOPO = topoSubject;
        end

        subjectFeatureDir = fullfile(analysisResultsPath, 'subject_features');

        if ~exist(subjectFeatureDir, 'dir')
            mkdir(subjectFeatureDir);
        end
        
        subjectFeatureFile = fullfile(subjectFeatureDir, [char(subjectName) '_subject_features.mat']);
        subjectFeature = subjectFeatures(validCount);
        save(subjectFeatureFile, 'subjectFeature', '-v7.3');
        
        fprintf('Saved subject-level features and plots for %s.\n', char(subjectName));
    end

    %% Save unified data file after subject-level feature extraction

    data.features = struct();
    data.features.subjectFeatures = subjectFeatures;
    data.features.summarySubjects = summarySubjects;

    data.features.ERP = struct();
    data.features.ERP.healthyERP = healthyERP;
    data.features.ERP.strokeERP = strokeERP;
    data.features.ERP.chanLabels_ref = chanLabels_ref;
    data.features.ERP.note = ...
        'Subject-wise ERP. ERP is computed by direct trial averaging from full-trial MI-band and delta-band data across all channels. No ERP baseline correction is applied in Step02.';

    data.features.PSD = struct();
    data.features.PSD.healthyPSD = healthyPSD;
    data.features.PSD.strokePSD = strokePSD;
    data.features.PSD.bandNames = psdBandNames;
    data.features.PSD.chanLabels_ref = chanLabels_ref;
    data.features.PSD.note = ...
        'Subject-wise PSD. Each band stores left baseline, left MI, right baseline, and right MI channel-level PSD.';

    data.features.ERDS = struct();
    data.features.ERDS.healthyERDS = healthyERDS;
    data.features.ERDS.strokeERDS = strokeERDS;
    data.features.ERDS.bandNames = erdersBands;
    data.features.ERDS.chanLabels_ref = chanLabels_ref;
    data.features.ERDS.note = ...
        'Subject-wise ERD/ERS. Mu and beta curves are stored for all channels left and right imagery.';
    
    data.features.TFR = struct();
    data.features.TFR.healthyTFR = healthyTFR;
    data.features.TFR.strokeTFR = strokeTFR;
    data.features.TFR.bandDefs = tfrBandDefs;
    data.features.TFR.chanLabels_ref = chanLabels_ref;
    data.features.TFR.note = ...
        'Subject-wise multi-band TFR channel-time summaries are stored for left and right imagery in mu, beta, and broad 8-30 Hz bands.';
    
    data.features.ASSI = struct();
    data.features.ASSI.healthyASSI = healthyASSI;
    data.features.ASSI.strokeASSI = strokeASSI;
    data.features.ASSI.bandNames = assiBandNames;
    data.features.ASSI.chanLabels_ref = chanLabels_ref;
    data.features.ASSI.note = ...
        'Subject-wise all-pair asymmetry index using homologous left-right electrode pairs.';
    
    data.features.TOPO = struct();
    data.features.TOPO.healthyTOPO = healthyTOPO;
    data.features.TOPO.strokeTOPO = strokeTOPO;
    data.features.TOPO.bandNames = topoBandNames;
    data.features.TOPO.chanLabels_ref = chanLabels_ref;
    data.features.TOPO.note = ...
        'Subject-wise channel-power features for each band and channel.';

    fprintf('\nSaving unified data file after subject-level feature extraction...\n');
    save(featuresMatPath, 'data', '-v7.3');
    fprintf('Saved: %s\n', featuresMatPath);
end

%% ========================================================================
% PART 2: GROUP-LEVEL VISUALIZATION FROM SAVED SUBJECT FEATURES
%
% Healthy subjects are averaged at the group level because they represent a
% relatively homogeneous reference cohort. Stroke subjects are retained mainly
% at the subject level because post-stroke EEG can vary substantially with
% lesion location, impairment severity, recovery stage, and neuroplastic
% reorganization. Stroke group averages are used only for broad visualization
% and should be interpreted cautiously.
% ========================================================================

if doGroupVisualization

    disp(' ');
    disp('================================================================================');
    disp('PART 2: GROUP-LEVEL VISUALIZATION');
    disp('================================================================================');

    Sload = load(featuresMatPath, 'data');
    data = Sload.data;

    if ~isfield(data, 'features') || ~isfield(data.features, 'subjectFeatures')
        error('features.mat does not contain data.features.subjectFeatures.');
    end

    subjectFeatures = data.features.subjectFeatures;

    if isempty(subjectFeatures)
        error('No subject features found for group-level averaging.');
    end

    groups = {subjectFeatures.group};
    healthyIdx = strcmpi(groups, 'healthy');
    strokeIdx = strcmpi(groups, 'stroke');

    healthySubjects = subjectFeatures(healthyIdx);
    strokeSubjects = subjectFeatures(strokeIdx);

    fprintf('Healthy subjects available for group averages: %d\n', numel(healthySubjects));
    fprintf('Stroke subjects retained subject-wise only: %d\n', numel(strokeSubjects));

    if isempty(healthySubjects)
        error('No healthy subjects found for group averaging.');
    end

    groupData = struct();
    
    groupData.note = ['Healthy and stroke group-level features are both generated. ' ...
        'Healthy group averages are used as the neurologically intact reference pattern. ' ...
        'Stroke group averages are used for broad visualization only and should be interpreted cautiously because acute stroke EEG can vary substantially across patients due to lesion location, impairment severity, recovery stage, and neuroplastic reorganization. ' ...
        'Primary healthy-vs-stroke inference is performed using subject-level statistics.'];
    
    groupData.nHealthy = numel(healthySubjects);
    groupData.nStroke = numel(strokeSubjects);
    
    if isempty(strokeSubjects)
        error('No stroke subjects found for stroke group feature generation.');
    end
    
    groupData.healthy = struct();
    groupData.stroke = struct();

    %% --------------------------------------------------------------------
    % ERP GROUP AVERAGE: HEALTHY AND STROKE, MI AND DELTA, ALL CHANNELS
    % ---------------------------------------------------------------------
    
    fprintf('Computing healthy and stroke group ERP averages.\n');
    
    erpGroupDir = fullfile(modalityRoots.ERP, 'group_level');
    
    groupData.healthy.ERP = Utility_Functions.average_group_erp_mi_delta(healthySubjects);
    groupData.stroke.ERP  = Utility_Functions.average_group_erp_mi_delta(strokeSubjects);
    
    save(fullfile(erpGroupDir, 'group_ERP_MI_Delta_healthy_stroke.mat'), ...
        'groupData', '-v7.3');
    
    % Healthy ERP heatmaps
    Utility_Functions.plot_group_erp_heatmap_all_channels( ...
        groupData.healthy.ERP.MI, ...
        fullfile(erpGroupDir, 'healthy_group_ERP_MI_all_channels_heatmap'), ...
        'Healthy Group Average | MI-band ERP');
    
    Utility_Functions.plot_group_erp_heatmap_all_channels( ...
        groupData.healthy.ERP.Delta, ...
        fullfile(erpGroupDir, 'healthy_group_ERP_Delta_all_channels_heatmap'), ...
        'Healthy Group Average | Delta-band ERP');
    
    % Stroke ERP heatmaps
    Utility_Functions.plot_group_erp_heatmap_all_channels( ...
        groupData.stroke.ERP.MI, ...
        fullfile(erpGroupDir, 'stroke_group_ERP_MI_all_channels_heatmap'), ...
        'Stroke Group Average | MI-band ERP');
    
    Utility_Functions.plot_group_erp_heatmap_all_channels( ...
        groupData.stroke.ERP.Delta, ...
        fullfile(erpGroupDir, 'stroke_group_ERP_Delta_all_channels_heatmap'), ...
        'Stroke Group Average | Delta-band ERP');

    %% --------------------------------------------------------------------
    % PSD GROUP AVERAGE: HEALTHY VS STROKE, ALL CHANNELS, ALL BANDS
    % ---------------------------------------------------------------------
    
    fprintf('Computing group PSD averages: stroke baseline, stroke MI, healthy baseline, healthy MI.\n');
    
    psdGroupDir = fullfile(modalityRoots.PSD, 'group_level');
    
    groupData.comparison = struct();
    groupData.comparison.PSD = Utility_Functions.average_group_psd_healthy_stroke( ...
        healthySubjects, strokeSubjects);
    
    save(fullfile(psdGroupDir, 'group_PSD_healthy_stroke_all_bands.mat'), ...
        'groupData', '-v7.3');
    
    for b = 1:length(groupData.comparison.PSD.bandNames)
    
        bandName = groupData.comparison.PSD.bandNames{b};
    
        Utility_Functions.plot_group_psd_healthy_stroke_bars( ...
            groupData.comparison.PSD.(bandName), ...
            groupData.comparison.PSD.chanLabels, ...
            fullfile(psdGroupDir, ['group_PSD_' bandName]), ...
            ['Group Average | ' upper(bandName) ' PSD']);
    end

    %% --------------------------------------------------------------------
    % ERD/ERS GROUP AVERAGE: HEALTHY AND STROKE, ALL CHANNELS, MU AND BETA
    % ---------------------------------------------------------------------
    
    fprintf('Computing healthy and stroke group ERD/ERS averages.\n');
    
    erdsGroupDir = fullfile(modalityRoots.ERDS, 'group_level');
    
    groupData.healthy.ERDS = Utility_Functions.average_group_erders_all_channels(healthySubjects);
    groupData.stroke.ERDS  = Utility_Functions.average_group_erders_all_channels(strokeSubjects);
    
    save(fullfile(erdsGroupDir, 'group_ERDS_healthy_stroke_all_channels.mat'), ...
        'groupData', '-v7.3');
    
    Utility_Functions.plot_group_erders_all_channels( ...
        groupData.healthy.ERDS, ...
        fullfile(erdsGroupDir, 'healthy_group_ERDS_all_channels'), ...
        'Healthy Group Average | All-Channel Mu/Beta ERD/ERS');
    
    Utility_Functions.plot_group_erders_all_channels( ...
        groupData.stroke.ERDS, ...
        fullfile(erdsGroupDir, 'stroke_group_ERDS_all_channels'), ...
        'Stroke Group Average | All-Channel Mu/Beta ERD/ERS');

    %% --------------------------------------------------------------------
    % TFR GROUP AVERAGE: HEALTHY AND STROKE, ALL CHANNELS
    % ---------------------------------------------------------------------
    
    fprintf('Computing healthy and stroke group TFR averages.\n');
    
    tfrGroupDir = fullfile(modalityRoots.TFR, 'group_level');
    
    groupData.healthy.TFR = Utility_Functions.average_group_tfr_all_channels(healthySubjects);
    groupData.stroke.TFR  = Utility_Functions.average_group_tfr_all_channels(strokeSubjects);
    
    save(fullfile(tfrGroupDir, 'group_TFR_healthy_stroke_all_channels.mat'), ...
        'groupData', '-v7.3');
    
    Utility_Functions.plot_group_tfr_all_channels( ...
        groupData.healthy.TFR, tfrColorLimits, ...
        fullfile(tfrGroupDir, 'healthy_group_TFR_all_channels'), ...
        'Healthy Group Average | All-Channel TFR');
    
    Utility_Functions.plot_group_tfr_all_channels( ...
        groupData.stroke.TFR, tfrColorLimits, ...
        fullfile(tfrGroupDir, 'stroke_group_TFR_all_channels'), ...
        'Stroke Group Average | All-Channel TFR');

    %% --------------------------------------------------------------------
    % ASSI GROUP AVERAGE: HEALTHY AND STROKE, ALL LEFT/RIGHT PAIRS
    % ---------------------------------------------------------------------
    
    fprintf('Computing healthy and stroke group ASSI averages.\n');
    
    assiGroupDir = fullfile(modalityRoots.ASSI, 'group_level');
    
    groupData.healthy.ASSI = Utility_Functions.average_group_assi_all_pairs(healthySubjects);
    groupData.stroke.ASSI  = Utility_Functions.average_group_assi_all_pairs(strokeSubjects);
    
    save(fullfile(assiGroupDir, 'group_ASSI_healthy_stroke_all_pairs.mat'), ...
        'groupData', '-v7.3');
    
    Utility_Functions.plot_group_assi_all_pairs( ...
        groupData.healthy.ASSI, ...
        fullfile(assiGroupDir, 'healthy_group_ASSI_all_pairs'), ...
        'Healthy Group Average | All-Pair Lateralization');
    
    Utility_Functions.plot_group_assi_all_pairs( ...
        groupData.stroke.ASSI, ...
        fullfile(assiGroupDir, 'stroke_group_ASSI_all_pairs'), ...
        'Stroke Group Average | All-Pair Lateralization');

    %% --------------------------------------------------------------------
    % TOPO / CHANNEL POWER GROUP AVERAGE: HEALTHY AND STROKE
    % ---------------------------------------------------------------------
    
    fprintf('Computing healthy and stroke group TOPO/channel-power averages.\n');
    
    topoGroupDir = fullfile(modalityRoots.TOPO, 'group_level');
    
    groupData.healthy.TOPO = Utility_Functions.average_group_topo_channel_power(healthySubjects);
    groupData.stroke.TOPO  = Utility_Functions.average_group_topo_channel_power(strokeSubjects);
    
    save(fullfile(topoGroupDir, 'group_TOPO_healthy_stroke_channel_power.mat'), ...
        'groupData', '-v7.3');
    
    Utility_Functions.plot_group_channel_power_summary( ...
        groupData.healthy.TOPO, ...
        fullfile(topoGroupDir, 'healthy_group_TOPO_channel_power'), ...
        'Healthy Group Average | Channel Power');
    
    Utility_Functions.plot_group_channel_power_summary( ...
        groupData.stroke.TOPO, ...
        fullfile(topoGroupDir, 'stroke_group_TOPO_channel_power'), ...
        'Stroke Group Average | Channel Power');

    %% Save updated unified feature file

    data.groupAverages = struct();
    data.groupAverages = groupData;
    
    data.groupAverages.interpretationNote = ...
        ['Stroke group-level features were generated for visualization and exploratory interpretation. ' ...
         'They should not be interpreted as a stable normative stroke signature because acute stroke physiology can vary across patients due to lesion location, impairment severity, time post-stroke, and neuroplastic reorganization. ' ...
         'Primary healthy-vs-stroke comparisons are performed using subject-level statistical tests.'];

    fprintf('\nSaving unified data file after healthy group-level visualization...\n');
    save(featuresMatPath, 'data', '-v7.3');
    fprintf('Saved: %s\n', featuresMatPath);
end

%% ========================================================================
% PART 3: WINDOWED FEATURE STATISTICS
% ---------------------------------------------------------------------
%
% Statistical comparisons are subject-level, not trial-level.
%
% For each channel/band/feature, the primary comparisons are:
%   1) Healthy baseline vs healthy MI     -> paired t-test
%   2) Stroke baseline vs stroke MI       -> paired t-test
%   3) Healthy MI vs stroke MI            -> Welch independent t-test
%
% FDR correction is applied within each comparison family across features.
% Nonparametric tests are retained only as secondary exploratory checks.
% ========================================================================

if doStatisticalAnalysis

    disp(' ');
    disp('================================================================================');
    disp('PART 3: WINDOWED FEATURE STATISTICS');
    disp('================================================================================');

    Sload = load(featuresMatPath, 'data');
    data = Sload.data;

    if ~isfield(data, 'features') || ~isfield(data.features, 'subjectFeatures')
        error('features.mat does not contain data.features.subjectFeatures.');
    end

    subjectFeatures = data.features.subjectFeatures;

    if isempty(subjectFeatures)
        error('No subject features found for statistical analysis.');
    end

    groups = {subjectFeatures.group};
    healthyIdx = strcmpi(groups, 'healthy');
    strokeIdx  = strcmpi(groups, 'stroke');

    healthySubjects = subjectFeatures(healthyIdx);
    strokeSubjects  = subjectFeatures(strokeIdx);

    fprintf('Healthy subjects for statistics: %d\n', numel(healthySubjects));
    fprintf('Stroke subjects for statistics: %d\n', numel(strokeSubjects));

    if isempty(healthySubjects) || isempty(strokeSubjects)
        error('Need both healthy and stroke subject features for statistics.');
    end

    statsRoot = fullfile(analysisResultsPath, 'statistics');

    if ~exist(statsRoot, 'dir')
        mkdir(statsRoot);
    end

    %% Folder for post-statistics significant feature plots
    sigPlotRoot = fullfile(statsRoot, 'significant_feature_plots');
    
    if ~exist(sigPlotRoot, 'dir')
        mkdir(sigPlotRoot);
    end

    % Windowed feature statistics.
    % TOPO is included because subject-level TOPO now stores both baseline and MI
    % channel-power values in dB.
    featureTypesForStats = {'PSD', 'ERDS', 'ASSI', 'TOPO'};

    statsResults = struct();

    for fType = 1:length(featureTypesForStats)

        featureType = featureTypesForStats{fType};

        fprintf('Computing %s statistics...\n', featureType);

        [featureNames, healthyBaselineMat, healthyMIMat, strokeBaselineMat, strokeMIMat] = ...
            Utility_Functions.collect_windowed_feature_matrices( ...
                featureType, healthySubjects, strokeSubjects);

        statsOut = Utility_Functions.run_windowed_feature_stats( ...
            featureType, ...
            featureNames, ...
            healthyBaselineMat, ...
            healthyMIMat, ...
            strokeBaselineMat, ...
            strokeMIMat, ...
            alpha);

        statsResults.(featureType) = statsOut;

        allCsv = fullfile(statsRoot, [featureType '_windowed_statistics_all.csv']);
        healthyCsv = fullfile(statsRoot, [featureType '_healthy_baseline_vs_MI.csv']);
        strokeCsv = fullfile(statsRoot, [featureType '_stroke_baseline_vs_MI.csv']);
        groupCsv = fullfile(statsRoot, [featureType '_healthyMI_vs_strokeMI.csv']);

        writetable(statsOut.all, allCsv);
        writetable(statsOut.healthyBaselineVsMI, healthyCsv);
        writetable(statsOut.strokeBaselineVsMI, strokeCsv);
        writetable(statsOut.healthyMIvsStrokeMI, groupCsv);

        %% Post-statistics visualization: significant feature plots
        % These plots only display features that survive FDR correction.
        % They are intended to emphasize the feature/channel/band effects that are
        % statistically meaningful, rather than showing every extracted feature.
        
        featureSigPlotDir = fullfile(sigPlotRoot, featureType);
        
        if ~exist(featureSigPlotDir, 'dir')
            mkdir(featureSigPlotDir);
        end
        
        Utility_Functions.plot_significant_stats_by_comparison( ...
            statsOut.all, ...
            featureSigPlotDir, ...
            featureType, ...
            20);
        
        Utility_Functions.plot_significant_feature_count_summary( ...
            statsOut.all, ...
            fullfile(featureSigPlotDir, [featureType '_significant_feature_counts']), ...
            [featureType ' | Significant Feature Counts']);

        statsResults.(featureType).outputFiles = struct();
        statsResults.(featureType).outputFiles.allCsv = allCsv;
        statsResults.(featureType).outputFiles.healthyCsv = healthyCsv;
        statsResults.(featureType).outputFiles.strokeCsv = strokeCsv;
        statsResults.(featureType).outputFiles.groupCsv = groupCsv;
    end

    %% Combined significant-feature count summary across all feature types
        
        combinedStatsTable = table();
        
        statFeatureTypes = fieldnames(statsResults);
        
        for sf = 1:length(statFeatureTypes)
        
            thisFeatureType = statFeatureTypes{sf};
        
            if isfield(statsResults.(thisFeatureType), 'all')
                combinedStatsTable = [combinedStatsTable; statsResults.(thisFeatureType).all];
            end
        end
        
        if ~isempty(combinedStatsTable)
            Utility_Functions.plot_significant_feature_count_summary( ...
                combinedStatsTable, ...
                fullfile(sigPlotRoot, 'ALL_FEATURES_significant_feature_counts'), ...
                'All Features | Significant Feature Counts');
        end

    data.statistics = struct();
    data.statistics.note = ...
        ['Statistics are computed using subject-level windowed feature values. ' ...
         'Within-group baseline-vs-MI comparisons use paired tests. ' ...
         'Healthy-vs-stroke MI comparisons use independent tests.'];

    data.statistics.results = statsResults;

    fprintf('\nSaving unified data file after statistical analysis...\n');
    save(featuresMatPath, 'data', '-v7.3');
    fprintf('Saved: %s\n', featuresMatPath);
end
